/**
 * File: p2p-kids-marketplace/src/components/molecules/__tests__/ResumeDraftBanner.test.tsx
 * MODULE-04 LISTING-V3-007: Unit tests for ResumeDraftBanner component
 */

import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { ResumeDraftBanner } from '../ResumeDraftBanner';
import { ItemDraft } from '../../../types/listing';

const mockDraft: ItemDraft = {
  id: 'draft-1',
  seller_id: 'seller-1',
  bulk_upload_id: null,
  draft_data: {
    title: 'Test Draft',
    description: 'Test description',
    price: 50,
    photo_urls: ['https://example.com/photo1.jpg'],
  },
  photo_urls: ['https://example.com/photo1.jpg'],
  ai_suggestions: null,
  step: 'photos',
  created_at: new Date(Date.now() - 3600000).toISOString(), // 1 hour ago
  updated_at: new Date(Date.now() - 1800000).toISOString(), // 30 min ago
  expires_at: new Date(Date.now() + 86400000 * 7).toISOString(), // 7 days from now
};

const mockBulkDraft: ItemDraft = {
  ...mockDraft,
  id: 'draft-2',
  bulk_upload_id: 'bulk-1',
};

describe('ResumeDraftBanner', () => {
  const mockOnResume = jest.fn();
  const mockOnDismiss = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders nothing when no drafts provided', () => {
    const { queryByTestId } = render(
      <ResumeDraftBanner drafts={[]} onResume={mockOnResume} onDismiss={mockOnDismiss} />
    );

    expect(queryByTestId('resume-draft-banner')).toBeNull();
  });

  it('renders banner with draft count when drafts exist', () => {
    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft, mockBulkDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    expect(getByTestId('resume-draft-banner')).toBeTruthy();
    expect(getByTestId('resume-draft-banner-title')).toHaveTextContent('2 unfinished listings');
  });

  it('shows singular text when only one draft', () => {
    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    expect(getByTestId('resume-draft-banner-title')).toHaveTextContent('1 unfinished listing');
  });

  it('calls onResume with correct params for single item draft when Continue pressed', () => {
    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    fireEvent.press(getByTestId('resume-draft-banner-resume-button'));

    expect(mockOnResume).toHaveBeenCalledWith('draft-1', false);
  });

  it('calls onResume with correct params for bulk draft when Continue pressed', () => {
    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockBulkDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    fireEvent.press(getByTestId('resume-draft-banner-resume-button'));

    expect(mockOnResume).toHaveBeenCalledWith('draft-2', true);
  });

  it('calls onDismiss when dismiss button pressed', () => {
    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    fireEvent.press(getByTestId('resume-draft-banner-dismiss-button'));

    expect(mockOnDismiss).toHaveBeenCalled();
  });

  it('uses most recent draft when multiple drafts exist', () => {
    const olderDraft: ItemDraft = {
      ...mockDraft,
      id: 'draft-old',
      updated_at: new Date(Date.now() - 7200000).toISOString(), // 2 hours ago
    };

    const { getByTestId } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft, olderDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    fireEvent.press(getByTestId('resume-draft-banner-resume-button'));

    // Should use the first draft in the array (most recent)
    expect(mockOnResume).toHaveBeenCalledWith('draft-1', false);
  });

  it('has correct accessibility labels', () => {
    const { getByLabelText } = render(
      <ResumeDraftBanner 
        drafts={[mockDraft]} 
        onResume={mockOnResume} 
        onDismiss={mockOnDismiss} 
      />
    );

    expect(getByLabelText('Resume listing')).toBeTruthy();
    expect(getByLabelText('Dismiss banner')).toBeTruthy();
  });
});

import React from 'react';
import { render, fireEvent, waitFor } from '@testing-library/react-native';
import MyListingsScreen from '../../screens/listing/MyListingsScreen';
import { useAuth } from '../../hooks/useAuth';
import { getMyListings, getListingSummary, deleteListing } from '../../services/listing';
import { getActiveDrafts } from '../../services/draftService';

jest.mock('../../hooks/useAuth');
jest.mock('../../services/listing');
jest.mock('../../services/draftService');

jest.mock('@react-navigation/native', () => ({
  useFocusEffect: (callback: () => void) => {
    // Trigger once on mount to simulate screen focus without re-render loops.
    const React = require('react');
    React.useEffect(() => {
      callback();
    }, []);
  },
}));

jest.mock('../../components/organisms/BottomNavBar', () => {
  return function MockBottomNavBar() {
    return null;
  };
});

const mockUseAuth = useAuth as jest.MockedFunction<typeof useAuth>;
const mockGetMyListings = getMyListings as jest.MockedFunction<typeof getMyListings>;
const mockGetListingSummary = getListingSummary as jest.MockedFunction<typeof getListingSummary>;
const mockGetActiveDrafts = getActiveDrafts as jest.MockedFunction<typeof getActiveDrafts>;

const mockNavigation = {
  navigate: jest.fn(),
};

describe('MyListingsScreen', () => {
  beforeEach(() => {
    jest.clearAllMocks();

    mockUseAuth.mockReturnValue({
      user: { id: 'seller-1' } as any,
      session: {
        user: { id: 'seller-1' },
      } as any,
      loading: false,
      signOut: jest.fn(),
    });

    mockGetListingSummary.mockResolvedValue({
      total_active: 1,
      total_sold: 0,
      total_earnings_dollars: 0,
    });
    mockGetActiveDrafts.mockResolvedValue([]);

    (deleteListing as jest.Mock).mockResolvedValue(undefined);
  });

  it('opens ListingSafetyReview when seller taps a rejected listing card', async () => {
    mockGetMyListings.mockResolvedValue([
      {
        id: 'listing-rejected-1',
        seller_id: 'seller-1',
        title: 'Rejected stroller',
        description: 'Flagged and rejected item',
        price: 55,
        category_id: null,
        condition: 'good',
        status: 'rejected',
        accepts_swap_points: false,
        seller_subscription_status_at_creation: null,
        flagged_at: '2026-03-29T10:00:00Z',
        rejected_at: '2026-03-29T11:00:00Z',
        rejection_reason: 'Safety concern',
        appeal_count: 1,
        created_at: '2026-03-29T09:00:00Z',
        updated_at: '2026-03-29T11:00:00Z',
        sold_at: null,
        images: [],
      } as any,
    ]);

    const { findByLabelText } = render(
      <MyListingsScreen navigation={mockNavigation as any} />
    );

    await waitFor(() => {
      expect(mockGetMyListings).toHaveBeenCalledWith('seller-1');
    });

    const cardButton = await findByLabelText('Open details for Rejected stroller');
    fireEvent.press(cardButton);

    expect(mockNavigation.navigate).toHaveBeenCalledWith('ListingSafetyReview', {
      listing_id: 'listing-rejected-1',
    });
  });
});

